/* ===================== BÀI 2 · EU, BIU và hàng đợi lệnh ===================== */
/* Bài 2 · EU, BIU và hàng đợi lệnh (AMTS-EMB-002-M01-L02, X86-002) — sinh bởi tools/author/mpu8086/l02.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const PV2=[{"label": "Ví dụ: số byte và số chu kỳ của từng lệnh", "code": "; Ví dụ 1: số byte mã và số chu kỳ EU của từng lệnh\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H               ; 3 byte, 4 chu kỳ\n        MOV     BX, AX                  ; 2 byte, 2 chu kỳ\n        INC     BX                      ; 1 byte, 2 chu kỳ\n        ADD     AX, BX                  ; 2 byte, 3 chu kỳ\n        MOV     CL, 5                   ; 2 byte, 4 chu kỳ\n        NOP                             ; 1 byte, 3 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mở phần Mã máy và chu kỳ: mỗi hàng có byte mã và số chu kỳ. Số byte và số chu kỳ không tỉ lệ với nhau: INC BX 1 byte, 2 chu kỳ; NOP 1 byte nhưng 3 chu kỳ; MOV AX, 1234h 3 byte, 4 chu kỳ. Sáu lệnh đầu: 11 byte, 18 chu kỳ theo bảng, nên cận nạp 2 × 11 = 22 chu kỳ lớn hơn. Đoán trước: sau ADD AX, BX, AX bằng bao nhiêu (hệ 16)? Đáp án 2469h (1234h + 1235h)."}, {"label": "Ví dụ: MUL chạy lâu, BIU nạp đầy hàng đợi", "code": "; Ví dụ 2: MUL chạy lâu, BIU kịp nạp đầy hàng đợi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?                       ; kết quả 16 bit\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 200                 ; số bị nhân\n        MOV     BL, 3                   ; số nhân\n        MUL     BL                      ; AX = AL × BL, 70 chu kỳ trở lên\n        MOV     kq, AX                  ; ghi 600 = 0258h ra bộ nhớ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "MUL BL mất 70 chu kỳ (bảng ghi 70–77, trình mô phỏng lấy cận dưới). Trong lúc đó BIU nạp đầy 6 byte rồi rảnh: xem đoạn “MUL BL chạy lâu” ở mô hình hàng đợi mục 2.3. Biến kq = 0258h (600 = 200 × 3), lưu kiểu little-endian 58 02. Đoán trước: sau MUL BL, AX bằng bao nhiêu (hệ 16)? Đáp án 0258h."}, {"label": "Bẫy: bảng ghi 24 chu kỳ, EU vẫn phải chờ", "code": "; Bẫy: bảng ghi 24 chu kỳ nhưng EU phải chờ byte lệnh\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H               ; mỗi lệnh 3 byte, 4 chu kỳ\n        MOV     BX, 1234H\n        MOV     CX, 1234H\n        MOV     DX, 1234H\n        MOV     SI, 1234H\n        MOV     DI, 1234H               ; 6 lệnh: 18 byte, 24 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: bảng ghi 6 lệnh × 4 = 24 chu kỳ, nhưng 6 lệnh dài 18 byte nên BIU cần ít nhất 36 chu kỳ để nạp; mô hình hàng đợi cho 40 chu kỳ trên 8086 và 76 trên 8088. Trình mô phỏng chỉ cộng bảng nên hiện 24. Sửa: Ví dụ 4. Đoán trước: cận nạp 2 × số byte của 6 lệnh là bao nhiêu chu kỳ? Đáp án 36."}, {"label": "Ví dụ: cùng kết quả, mã gọn hơn", "code": "; Ví dụ 4: cùng kết quả với Ví dụ 3, mã gọn hơn\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AX, 1234H               ; 3 byte, 4 chu kỳ\n        MOV     BX, AX                  ; mỗi lệnh 2 byte, 2 chu kỳ\n        MOV     CX, AX\n        MOV     DX, AX\n        MOV     SI, AX\n        MOV     DI, AX                  ; 6 lệnh: 13 byte, 14 chu kỳ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Cùng kết quả với Ví dụ 3 (sáu thanh ghi bằng 1234h) nhưng chỉ một lệnh có số tức thời; năm lệnh MOV r16, AX mỗi lệnh 2 byte, 2 chu kỳ. 13 byte, 14 chu kỳ theo bảng; mô hình hàng đợi 30 chu kỳ so với 40. Đoán trước: sau MOV SI, AX, SI bằng bao nhiêu? Đáp án 1234h."}, {"label": "Bẫy: lệnh nhảy xóa hàng đợi", "code": "; Bẫy: lệnh nhảy làm mất các byte đã nạp trước\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 02H\n        MOV     DL, 'A'\n        JMP     tiep                    ; nhảy: hàng đợi bị xóa\n        MOV     DL, 'B'                 ; đã nạp trước nhưng không chạy\ntiep:\n        INT     21H                     ; in A\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: JMP tiep (EB 02, 15 chu kỳ) nhảy qua MOV DL, 'B'. Các byte B2 42 của lệnh bị nhảy qua đã được BIU nạp trước rồi bị bỏ khi hàng đợi bị xóa; EU chờ nạp lại từ nhãn tiep. Màn hình chỉ có chữ A. Đoán trước: lệnh MOV DL, 'B' có chạy không? Đáp án không."}, {"label": "Bẫy: code tự sửa, trình mô phỏng khác CPU", "code": "; Bẫy: chương trình tự sửa lệnh kế tiếp của chính nó\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 02H\n        MOV     BYTE PTR CS:[SUA+1], 'B' ; sửa số tức thời\nSUA:\n        MOV     DL, 'A'                 ; byte 41h có thể đã ở hàng đợi\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: lệnh MOV BYTE PTR CS:[SUA+1], 'B' ghi 42h đè lên số tức thời 41h của lệnh ngay sau. Trình mô phỏng không có hàng đợi nên đọc byte mới và in B. Trên CPU thật, theo mô hình hàng đợi (đoạn “Code tự sửa mình”), byte 41h đã nằm trong hàng đợi từ chu kỳ 20, trước lúc ghi (chu kỳ 31–34), nên CPU có thể vẫn in A. Kết quả trên chip thật cần kiểm (PENDING). Đừng viết code tự sửa. Đoán trước: trình mô phỏng in chữ gì? Đáp án B."}];
const sim2=makeX86Sim(document.getElementById("x86-l2"),{id:"s2",presets:PV2,file:"BAI2.ASM"});
makeX86Ex(document.getElementById("ex-l2"),sim2,[{"t": "Một phím, bốn thanh ghi", "d": "Đọc một phím bằng INT 21h hàm 08h (không hiện). Đặt BX, CX, DX và SI cùng bằng mã ASCII của phím, byte cao bằng 0 (ví dụ phím A: BX = CX = DX = SI = 0041h). Kết thúc bằng INT 21h hàm 4Ch. Phím là một ký tự ASCII in được (20h–7Eh).", "start": "; Bài tập 1: một phím, bốn thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 08H                 ; đọc một phím, không hiện\n        INT     21H                     ; AL = mã ASCII, AH vẫn là 08h\n; Viết code ở đây: BX = CX = DX = SI = mã phím,\n; byte cao bằng 0\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "A", "regs": {"BX": 65, "CX": 65, "DX": 65, "SI": 65}}, {"dosExit": true, "in": "z", "regs": {"BX": 122, "CX": 122, "DX": 122, "SI": 122}}, {"dosExit": true, "in": "0", "regs": {"BX": 48, "CX": 48, "DX": 48, "SI": 48}}, {"dosExit": true, "in": " ", "regs": {"BX": 32, "CX": 32, "DX": 32, "SI": 32}}, {"dosExit": true, "in": "~", "regs": {"BX": 126, "CX": 126, "DX": 126, "SI": 126}}]}, {"t": "Gấp đôi ba lần trong thanh ghi", "d": "Đọc một phím chữ số 0–9 bằng INT 21h hàm 08h. Ghi giá trị d của chữ số (0–9) vào biến so, 2·d vào gap2, 4·d vào gap4 và 8·d vào gap8 (mỗi biến 1 byte). Chỉ dùng phép cộng và lệnh chép, không dùng MUL. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: gấp đôi ba lần trong thanh ghi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nso      DB      ?                       ; d\ngap2    DB      ?                       ; 2·d\ngap4    DB      ?                       ; 4·d\ngap8    DB      ?                       ; 8·d\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím chữ số\n        INT     21H\n; Viết code ở đây: đổi mã ASCII ra giá trị,\n; ghi so, gap2, gap4, gap8 (không dùng MUL)\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "3", "mem": [{"at": "so", "bytes": [3]}, {"at": "gap2", "bytes": [6]}, {"at": "gap4", "bytes": [12]}, {"at": "gap8", "bytes": [24]}]}, {"dosExit": true, "in": "0", "mem": [{"at": "so", "bytes": [0]}, {"at": "gap2", "bytes": [0]}, {"at": "gap4", "bytes": [0]}, {"at": "gap8", "bytes": [0]}]}, {"dosExit": true, "in": "9", "mem": [{"at": "so", "bytes": [9]}, {"at": "gap2", "bytes": [18]}, {"at": "gap4", "bytes": [36]}, {"at": "gap8", "bytes": [72]}]}, {"dosExit": true, "in": "1", "mem": [{"at": "so", "bytes": [1]}, {"at": "gap2", "bytes": [2]}, {"at": "gap4", "bytes": [4]}, {"at": "gap8", "bytes": [8]}]}, {"dosExit": true, "in": "7", "mem": [{"at": "so", "bytes": [7]}, {"at": "gap2", "bytes": [14]}, {"at": "gap4", "bytes": [28]}, {"at": "gap8", "bytes": [56]}]}]}, {"t": "Nhân 10 không dùng MUL", "d": "Đọc một phím chữ số 0–9 bằng INT 21h hàm 08h và ghi 10·d (0–90) vào biến kq (1 byte). Code mẫu đúng kết quả nhưng dùng MUL (70 chu kỳ trở lên). Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: nhân 10 không dùng MUL\n; Bản này đúng nhưng chậm: MUL mất 70 chu kỳ trở lên.\n; Hãy viết lại phần giữa bằng phép cộng.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DB      ?                       ; 10·d\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H                 ; đọc một phím chữ số\n        INT     21H\n        SUB     AL, '0'                 ; AL = d (0–9)\n        MOV     BL, 10\n        MUL     BL                      ; AX = AL × 10\n        MOV     kq, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"dosExit": true, "in": "3", "mem": [{"at": "kq", "bytes": [30]}]}, {"dosExit": true, "in": "0", "mem": [{"at": "kq", "bytes": [0]}]}, {"dosExit": true, "in": "9", "mem": [{"at": "kq", "bytes": [90]}]}, {"dosExit": true, "in": "1", "mem": [{"at": "kq", "bytes": [10]}]}, {"dosExit": true, "in": "5", "mem": [{"at": "kq", "bytes": [50]}]}, {"dosExit": true, "in": "7", "mem": [{"at": "kq", "bytes": [70]}]}], "perf": {"cycles": 150, "bytes": 32}}]);
